import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { ChevronLeft, Plus, Search } from 'lucide-react';
import './Transport.css'; // 确保引入对应的 CSS

const Transport = () => {
  const navigate = useNavigate();
  
  // 状态管理：控制当前选中的 Tab (Booking 或 Timetable)
  const [activeTab, setActiveTab] = useState('Booking');
  
  // 模拟数据：目前为空，用于触发 transport.png 的显示
  const [bookings, setBookings] = useState([]);

  const handleBack = () => {
    navigate('/');
  };

  return (
    <div className="transport-container">
      {/* 顶部导航栏 */}
      <nav className="transport-top-nav">
        <div className="back-arrow" onClick={handleBack}>
          <ChevronLeft size={24} color="#ffffff" strokeWidth={2.5} />
        </div>
        <span className="nav-title">Transport</span>
      </nav>

      <div className="transport-main-content">
        {/* Tab 切换栏：严格靠左对齐 */}
        <div className="transport-tabs-container">
          <div className="transport-tabs-left">
            <button 
              className={`trans-tab ${activeTab === 'Booking' ? 'active' : ''}`} 
              onClick={() => setActiveTab('Booking')}
            >
              Booking
            </button>
            <button 
              className={`trans-tab ${activeTab === 'Timetable' ? 'active' : ''}`} 
              onClick={() => setActiveTab('Timetable')}
            >
              Timetable
            </button>
          </div>
        </div>

        {/* 内容展示区 */}
        <div className="transport-scroll-area">
          {bookings.length === 0 ? (
            /* 空状态展示：显示 transport.png */
            <div className="transport-empty-state">
              <div className="empty-img-wrapper">
                <img 
                  src="/icon_img/transportp.png" 
                  alt="No Transport Record" 
                />
              </div>
              <p className="empty-text">No records found</p>
            </div>
          ) : (
            /* 这里预留给未来的列表渲染 */
            <div className="transport-list-view">
              {/* List items will go here */}
            </div>
          )}
        </div>
      </div>

      {/* 底部功能按钮：New Booking */}
      <div className="transport-action-footer">
        <button className="new-booking-btn" onClick={() => alert('New Transport Booking')}>
          <Plus size={20} />
          <span>New Booking</span>
        </button>
      </div>

      
    </div>
  );
};

export default Transport;
